// Stairway list management — C ref: stairs.c stairway_add
function stairway_add(x, y, up, isladder, dest) {
    const node = {
        sx: x, sy: y, up, isladder,
        tolev: { ...dest },
        u_traversed: false,
        next: game.stairs,
    };
    game.stairs = node;
}

// ── Stairway lookup ──

/** C ref: stairs.c stairway_at */
export function stairway_at(x, y) {
    for (let s = game.stairs; s; s = s.next)
        if (s.sx === x && s.sy === y) return s;
    return null;
}

/** C ref: stairs.c stairway_find_dir — first stairway with matching up. */
function stairway_find_dir(up) {
    const want = !!up;
    for (let s = game.stairs; s; s = s.next)
        if (!!s.up === want) return s;
    return null;
}

/** C ref: stairs.c stairway_find_type_dir `:88–96` — isladder and up. */
export function stairway_find_type_dir(isladder, up) {
    const wantLadder = !!isladder;
    const wantUp = !!up;
    for (let s = game.stairs; s; s = s.next) {
        if (!!s.isladder === wantLadder && !!s.up === wantUp) return s;
    }
    return null;
}

/** C ref: stairs.c stairway_find_from */
export function stairway_find_from(fromdlev, isladder) {
    const dnum = fromdlev?.dnum | 0;
    const dlevel = fromdlev?.dlevel | 0;
    const ladder = !!isladder;
    for (let s = game.stairs; s; s = s.next) {
        if ((s.tolev?.dnum | 0) === dnum
            && (s.tolev?.dlevel | 0) === dlevel
            && !!s.isladder === ladder) {
            return s;
        }
    }
    return null;
}

/**
 * C ref: stairs.c stairway_find_special_dir — branch stair whose
 * tolev.dnum != u.uz.dnum and up != want (C boolean !=).
 */
function stairway_find_special_dir(up) {
    const want = !!up;
    const dnum = game.u?.uz?.dnum ?? 0;
    for (let s = game.stairs; s; s = s.next) {
        if ((s.tolev?.dnum | 0) !== dnum && !!s.up !== want) return s;
    }
    return null;
}

/** C ref: stairs.c known_branch_stairs */
export function known_branch_stairs(sway) {
    return !!(sway && sway.tolev.dnum !== (game.u?.uz?.dnum ?? 0) && sway.u_traversed);
}

/**
 * C ref: stairs.c stairs_description — ordinary / Dlvl1-up / known-branch.
 * Deferred: Elemental Planes destination string when amulet + on_level planes
 * (C uses "to the Elemental Planes" vs generic "to the end game").
 */
export function stairs_description(sway, stcase = true) {
    if (!sway) return '';
    const tolev = sway.tolev || { dnum: 0, dlevel: 1 };
    const stairs = sway.isladder ? 'ladder' : (stcase ? 'staircase' : 'stairs');
    const updown = sway.up ? 'up' : 'down';
    if (!known_branch_stairs(sway)) {
        let out = `${stairs} ${updown}`;
        if (sway.u_traversed) {
            // C: specialdepth = quest_dnum || single_level_branch (knox);
            // to_dlev = specialdepth ? dunlev(&tolev) : depth(&tolev)
            const specialdepth = In_quest(tolev) || Is_knox_level(tolev);
            const to_dlev = specialdepth
                ? (tolev.dlevel | 0)
                : (depth_of_level(tolev) | 0);
            out += ` to level ${to_dlev}`;
        }
        return out;
    }
    const uz = game.u?.uz || {};
    if ((uz.dnum ?? 0) === 0 && (uz.dlevel ?? 1) === 1 && sway.up) {
        const haveAmulet = !!(game.u?.uhave?.amulet);
        if (!haveAmulet)
            return `${stairs} ${updown} out of the dungeon`;
        return `branch ${stairs} ${updown} to the end game`;
    }
    const dname = (game.dungeons?.[sway.tolev.dnum]?.dname || 'elsewhere')
        .replace(/^The /, 'the ');
    return `branch ${stairs} ${updown} to ${dname}`;
}

