function u_on_newpos(x, y) {
    game.u.ux = x;
    game.u.uy = y;
}
export { u_on_newpos };

// C ref: dungeon.h within_bounded_area
function within_bounded_area(x, y, lx, ly, hx, hy) {
    return x >= lx && x <= hx && y >= ly && y <= hy;
}

// C ref: mkmaze.c bad_location
function bad_location(x, y, nlx, nly, nhx, nhy) {
    const loc = game.level?.at(x, y);
    if (!loc) return true;
    if (occupied(x, y)) return true;
    if (within_bounded_area(x, y, nlx, nly, nhx, nhy)) return true;
    const okTyp = (loc.typ === CORR && game.level?.flags?.is_maze_lev)
        || loc.typ === ROOM
        || loc.typ === AIR;
    return !okTyp;
}

// C ref: mkmaze.c is_exclusion_zone
function is_exclusion_zone(type, x, y) {
    for (let ez = game.exclusion_zones; ez; ez = ez.next) {
        if (((type === LR_DOWNTELE
                && (ez.zonetype === LR_DOWNTELE || ez.zonetype === LR_TELE))
            || (type === LR_UPTELE
                && (ez.zonetype === LR_UPTELE || ez.zonetype === LR_TELE))
            || type === ez.zonetype)
            && within_bounded_area(x, y, ez.lx, ez.ly, ez.hx, ez.hy))
            return true;
    }
    return false;
}

// C ref: mkmaze.c put_lregion_here — place stair/branch/tele at (x,y)
function put_lregion_here(x, y, nlx, nly, nhx, nhy, rtype, oneshot, lev) {
    if (bad_location(x, y, nlx, nly, nhx, nhy)
        || is_exclusion_zone(rtype, x, y)) {
        if (!oneshot) return false;
        // C: deltrap undestroyable-safe then retry bad_location + exclusion
        const t = t_at(x, y);
        if (t) {
            // Named omission: undestroyable_trap gate + mtrapped clear
            let prev = null;
            for (let cur = game.ftrap; cur; prev = cur, cur = cur.ntrap) {
                if (cur === t) {
                    if (prev) prev.ntrap = cur.ntrap;
                    else game.ftrap = cur.ntrap;
                    break;
                }
            }
        }
        if (bad_location(x, y, nlx, nly, nhx, nhy)
            || is_exclusion_zone(rtype, x, y))
            return false;
    }
    switch (rtype) {
    case LR_TELE:
    case LR_UPTELE:
    case LR_DOWNTELE: {
        // C: monster here → oneshot rloc/limbo, else retry
        const mtmp = m_at(x, y);
        if (mtmp) {
            if (oneshot) {
                if (!rloc(mtmp, 0)) {
                    // m_into_limbo deferred
                }
            } else {
                return false;
            }
        }
        u_on_newpos(x, y);
        break;
    }
    case LR_PORTAL: {
        // C ref: mkmaze.c mkportal — MAGIC_PORTAL + dst dnum/dlevel
        const ttmp = maketrap(x, y, MAGIC_PORTAL);
        if (ttmp && lev) {
            ttmp.dst = { dnum: lev.dnum | 0, dlevel: lev.dlevel | 0 };
        }
        break;
    }
    case LR_DOWNSTAIR:
    case LR_UPSTAIR:
        mkstairs(x, y, rtype === LR_UPSTAIR ? 1 : 0, null);
        break;
    case LR_BRANCH:
        place_branch(is_branchlev(), x, y);
        break;
    }
    return true;
}

// C ref: mkmaze.c place_lregion
/**
 * C ref: dungeon.c u_on_rndspot — place hero via updest/dndest after
 * goto_level. After place_lregion, switch_terrain (D-1278; C :1636–1637)
 * so leftover Lev/Fly FROMOUTSIDE from solid rock unblocks. Unconditional
 * (not dest-typ gated like teleds / hurtle_step). Named: On_W_tower_level
 * gate; W-tower bit 2 at goto_level (D-1179).
 * stairs.c u_on_sstairs fallback is D-1287. cmd.c makemap_prepost
 * amulet|wiztower flags is D-1288. objnam wish is a separate caller.
 */
export async function u_on_rndspot(upflag) {
    const up = !!(upflag & 1);
    const was_in_W_tower = !!(upflag & 2);
    const dndest = game.dndest || {};
    const updest = game.updest || {};
    if (was_in_W_tower && dndest.nlx) {
        // On_W_tower_level gate deferred — use exclusion region when present
        place_lregion(
            dndest.nlx, dndest.nly, dndest.nhx, dndest.nhy,
            0, 0, 0, 0, LR_DOWNTELE, null,
        );
    } else if (up) {
        place_lregion(
            updest.lx | 0, updest.ly | 0, updest.hx | 0, updest.hy | 0,
            updest.nlx | 0, updest.nly | 0, updest.nhx | 0, updest.nhy | 0,
            LR_UPTELE, null,
        );
    } else {
        place_lregion(
            dndest.lx | 0, dndest.ly | 0, dndest.hx | 0, dndest.hy | 0,
            dndest.nlx | 0, dndest.nly | 0, dndest.nhx | 0, dndest.nhy | 0,
            LR_DOWNTELE, null,
        );
    }
    /* C dungeon.c:1636–1637 — might have just left solid rock. */
    const { switch_terrain } = await import('./hack.js');
    await switch_terrain();
}

export function place_lregion(lx, ly, hx, hy, nlx, nly, nhx, nhy, rtype, lev) {
    if (!lx) {
        // When rooms exist, let place_branch pick (avoid corridor branches)
        if (rtype === LR_BRANCH && (game.level?.nroom | 0)) {
            place_branch(is_branchlev(), 0, 0);
            return;
        }
        lx = 1;
        hx = COLNO - 1;
        ly = 0;
        hy = ROWNO - 1;
    }
    if (lx < 1) lx = 1;
    if (hx > COLNO - 1) hx = COLNO - 1;
    if (ly < 0) ly = 0;
    if (hy > ROWNO - 1) hy = ROWNO - 1;

    const oneshot = (lx === hx && ly === hy);
    for (let trycnt = 0; trycnt < 200; trycnt++) {
        const x = rn1((hx - lx) + 1, lx);
        const y = rn1((hy - ly) + 1, ly);
        if (put_lregion_here(x, y, nlx, nly, nhx, nhy, rtype, oneshot, lev))
            return;
    }
    for (let x = lx; x <= hx; x++)
        for (let y = ly; y <= hy; y++)
            if (put_lregion_here(x, y, nlx, nly, nhx, nhy, rtype, true, lev))
                return;
}

/** C ref: decl.c gb.bughack — preserve baalz insect legs during wallify. */
function bughack_state() {
    const g = game;
    if (!g.bughack) {
        g.bughack = {
            inarea: { x1: COLNO, y1: ROWNO, x2: 0, y2: 0 },
            delarea: { x1: COLNO, y1: ROWNO, x2: 0, y2: 0 },
        };
    }
    return g.bughack;
}

/**
 * C ref: mkmaze.c baalz_fixup — selective wallify of Baalzebub beetle
 * lair; pools mark leg joints; iron-bar eyes clear diggable in front.
 */
function baalz_fixup() {
    const g = game;
    const map = g.level;
    if (!map) return;
    const bh = bughack_state();
    let lastx = 0;
    let x = 0;
    const midy = (ROWNO / 2) | 0;
    for (lastx = x = 0; x < COLNO; ++x) {
        const loc = map.at(x, midy);
        if (loc && ((loc.wall_info || 0) & W_NONDIGGABLE) !== 0) {
            if (!lastx) bh.inarea.x1 = x + 1;
            lastx = x;
        }
    }
    bh.inarea.x2 = ((lastx > bh.inarea.x1) ? lastx : x) - 1;
    x = bh.inarea.x1;
    let lasty = 0;
    let y = 0;
    for (lasty = y = 0; y < ROWNO; ++y) {
        const loc = map.at(x, y);
        if (loc && ((loc.wall_info || 0) & W_NONDIGGABLE) !== 0) {
            if (!lasty) bh.inarea.y1 = y + 1;
            lasty = y;
        }
    }
    bh.inarea.y2 = ((lasty > bh.inarea.y1) ? lasty : y) - 1;
    for (x = bh.inarea.x1; x <= bh.inarea.x2; ++x) {
        for (y = bh.inarea.y1; y <= bh.inarea.y2; ++y) {
            const loc = map.at(x, y);
            if (!loc) continue;
            if (loc.typ === POOL) {
                loc.typ = HWALL;
                if (bh.delarea.x1 === COLNO) {
                    bh.delarea.x1 = x;
                    bh.delarea.y1 = y;
                } else {
                    bh.delarea.x2 = x;
                    bh.delarea.y2 = y;
                }
            } else if (loc.typ === IRONBARS) {
                if (isok(x - 1, y)
                    && ((map.at(x - 1, y)?.wall_info || 0) & W_NONDIGGABLE) !== 0) {
                    const a = map.at(x - 1, y);
                    if (a) a.wall_info = (a.wall_info || 0) & ~W_NONDIGGABLE;
                    if (isok(x - 2, y)) {
                        const b = map.at(x - 2, y);
                        if (b) b.wall_info = (b.wall_info || 0) & ~W_NONDIGGABLE;
                    }
                } else if (isok(x + 1, y)
                    && ((map.at(x + 1, y)?.wall_info || 0) & W_NONDIGGABLE) !== 0) {
                    const a = map.at(x + 1, y);
                    if (a) a.wall_info = (a.wall_info || 0) & ~W_NONDIGGABLE;
                    if (isok(x + 2, y)) {
                        const b = map.at(x + 2, y);
                        if (b) b.wall_info = (b.wall_info || 0) & ~W_NONDIGGABLE;
                    }
                }
            }
        }
    }
    wallification(
        Math.max(bh.inarea.x1 - 2, 1),
        Math.max(bh.inarea.y1 - 2, 0),
        Math.min(bh.inarea.x2 + 2, COLNO - 1),
        Math.min(bh.inarea.y2 + 2, ROWNO - 1),
    );
    x = bh.delarea.x1;
    y = bh.delarea.y1;
    {
        const loc = map.at(x, y);
        const below = map.at(x, y + 1);
        if (loc && isok(x, y)
            && (loc.typ === TLWALL || loc.typ === TRWALL)
            && isok(x, y + 1) && below?.typ === TUWALL) {
            loc.typ = (loc.typ === TLWALL) ? BRCORNER : BLCORNER;
            below.typ = HWALL;
            const mtmp = m_at(x, y);
            if (mtmp) rloc(mtmp, RLOC_ERR | RLOC_NOMSG);
        }
    }
    x = bh.delarea.x2;
    y = bh.delarea.y2;
    {
        const loc = map.at(x, y);
        const above = map.at(x, y - 1);
        if (loc && isok(x, y)
            && (loc.typ === TLWALL || loc.typ === TRWALL)
            && isok(x, y - 1) && above?.typ === TDWALL) {
            loc.typ = (loc.typ === TLWALL) ? TRCORNER : TLCORNER;
            above.typ = HWALL;
            const mtmp = m_at(x, y);
            if (mtmp) rloc(mtmp, RLOC_ERR | RLOC_NOMSG);
        }
    }
    bh.inarea.x1 = bh.delarea.x1 = COLNO;
    bh.inarea.y1 = bh.delarea.y1 = ROWNO;
    bh.inarea.x2 = bh.delarea.x2 = 0;
    bh.inarea.y2 = bh.delarea.y2 = 0;
}

/**
 * C ref: sp_lev.c levregion_add — get_location ANY_LOC unless in_islev /
 * del_islev, then append to gl.lregions. Exclude omitted → delarea -1 and
 * del_islev so get_location does not treat -1 as random.
 */
function levregion_add(lregion) {
    if (!lregion.in_islev) {
        const a = get_location(lregion.inarea.x1, lregion.inarea.y1, ANY_LOC, null);
        const b = get_location(lregion.inarea.x2, lregion.inarea.y2, ANY_LOC, null);
        lregion.inarea.x1 = a.x;
        lregion.inarea.y1 = a.y;
        lregion.inarea.x2 = b.x;
        lregion.inarea.y2 = b.y;
    }
    if (!lregion.del_islev) {
        const a = get_location(lregion.delarea.x1, lregion.delarea.y1, ANY_LOC, null);
        const b = get_location(lregion.delarea.x2, lregion.delarea.y2, ANY_LOC, null);
        lregion.delarea.x1 = a.x;
        lregion.delarea.y1 = a.y;
        lregion.delarea.x2 = b.x;
        lregion.delarea.y2 = b.y;
    }
    if (!game.lregions) game.lregions = [];
    game.lregions.push({
        ...lregion,
        inarea: { ...lregion.inarea },
        delarea: { ...lregion.delarea },
        rname: lregion.rname && typeof lregion.rname === 'object'
            ? { ...lregion.rname } : lregion.rname,
    });
}

/**
 * C ref: sp_lev.c lspo_teleport_region / l_get_lregion (unpacked table).
 * dir default "both" → LR_TELE. Missing exclude → delarea -1,-1,-1,-1 and
 * del_islev. Named omit: Lua argc parse; other load_* still push lregions
 * by hand (earth/fire/air/hell) rather than this helper.
 */
export function l_teleport_region(opts) {
    const region = opts.region;
    const exclude = opts.exclude;
    const dir = opts.dir || 'both';
    const rtype = dir === 'up' ? LR_UPTELE
        : dir === 'down' ? LR_DOWNTELE
        : LR_TELE;
    const lregion = {
        inarea: {
            x1: region[0] | 0, y1: region[1] | 0,
            x2: region[2] | 0, y2: region[3] | 0,
        },
        delarea: exclude
            ? {
                x1: exclude[0] | 0, y1: exclude[1] | 0,
                x2: exclude[2] | 0, y2: exclude[3] | 0,
            }
            : { x1: -1, y1: -1, x2: -1, y2: -1 },
        in_islev: !!opts.region_islev,
        del_islev: !!opts.exclude_islev,
        rtype,
        padding: 0,
        rname: { str: null },
    };
    if (!exclude || (exclude[0] | 0) < 0)
        lregion.del_islev = true;
    levregion_add(lregion);
}

/**
 * C ref: sp_lev.c lspo_levregion / l_get_lregion.
 * type default "stair-down". Missing exclude → delarea -1 and del_islev.
 */
const LREGION_TYPES = {
    'stair-down': LR_DOWNSTAIR,
    'stair-up': LR_UPSTAIR,
    portal: LR_PORTAL,
    branch: LR_BRANCH,
    teleport: LR_TELE,
    'teleport-up': LR_UPTELE,
    'teleport-down': LR_DOWNTELE,
};

export function l_levregion(opts) {
    const region = opts.region;
    const exclude = opts.exclude;
    const rtype = LREGION_TYPES[opts.type || 'stair-down'] ?? LR_DOWNSTAIR;
    const lregion = {
        inarea: {
            x1: region[0] | 0, y1: region[1] | 0,
            x2: region[2] | 0, y2: region[3] | 0,
        },
        delarea: exclude
            ? {
                x1: exclude[0] | 0, y1: exclude[1] | 0,
                x2: exclude[2] | 0, y2: exclude[3] | 0,
            }
            : { x1: -1, y1: -1, x2: -1, y2: -1 },
        in_islev: !!opts.region_islev,
        del_islev: !!opts.exclude_islev,
        rtype,
        padding: opts.padding | 0,
        rname: { str: opts.name ?? null },
    };
    if (!exclude || (exclude[0] | 0) < 0)
        lregion.del_islev = true;
    levregion_add(lregion);
}

/**
 * C ref: sp_lev.c lspo_exclusion.
 * des.exclusion({ type = "teleport"|"teleport-up"|"teleport-down"|
 *                 "monster-generation", region = { x1,y1,x2,y2 } }).
 * Default type "teleport". get_location(ANY_LOC|NO_LOC_WARN) so packed
 * coords become absolute (map origin, or croom lx/ly). Prepend onto
 * sve.exclusion_zones. Named omit: hellfill rnd_hell_prefab maps;
 * save_exclusions / load_exclusions.
 */
const EZ_TYPES = {
    teleport: LR_TELE,
    'teleport-up': LR_UPTELE,
    'teleport-down': LR_DOWNTELE,
    'monster-generation': LR_MONGEN,
};

export function lspo_exclusion(opts) {
    const typeName = opts?.type ?? 'teleport';
    const zonetype = EZ_TYPES[typeName] ?? LR_TELE;
    const region = opts.region;
    const croom = opts.croom ?? null;
    const a = get_location(region[0] | 0, region[1] | 0,
        ANY_LOC | NO_LOC_WARN, croom);
    const b = get_location(region[2] | 0, region[3] | 0,
        ANY_LOC | NO_LOC_WARN, croom);
    const ez = {
        zonetype,
        lx: a.x,
        ly: a.y,
        hx: b.x,
        hy: b.y,
        next: game.exclusion_zones || null,
    };
    game.exclusion_zones = ez;
}

/**
 * C ref: sp_lev.c lspo_gas_cloud.
 * gas_cloud({ x, y } | { coord } | { selection, damage?, ttl? }).
 * Coords go to create_gas_cloud size-1 (no get_location). Selection
 * uses create_gas_cloud_selection (bitmap 1×1 rects, ttl stays -1).
 * ttl > -2 overwrites after create. Default damage 0, ttl -2 (no
 * overwrite). If x,y are both -1, C reads the selection field.
 */
export async function lspo_gas_cloud(opts) {
    const tx = opts?.x ?? -1;
    const ty = opts?.y ?? -1;
    let x = tx | 0;
    let y = ty | 0;
    if (tx === -1 && ty === -1 && opts?.coord) {
        x = opts.coord[0] | 0;
        y = opts.coord[1] | 0;
    }
    let sel = null;
    if (x === -1 && y === -1) sel = opts?.selection ?? null;
    const damage = opts?.damage | 0;
    const ttl = opts?.ttl != null ? (opts.ttl | 0) : -2;
    const reg = sel
        ? await create_gas_cloud_selection(sel, damage)
        : await create_gas_cloud(x, y, 1, damage);
    if (ttl > -2) reg.ttl = ttl;
    return reg;
}

/** C ref: dungeon.c free_exclusions — drop the list on clear_level_structures. */
function free_exclusions() {
    game.exclusion_zones = null;
}

/* C mkmaze.c ORC_LEADER — migrate_orc leader dest = dungeon bottom. */
const ORC_LEADER = 1;
const orcfruit = ['paddle cactus', 'dwarven root'];

/** C dungeon.c dunlevs_in_dungeon — local (avoid extra import). */
function dunlevs_in_dungeon_maz(lev) {
    return game.dungeons?.[lev?.dnum | 0]?.num_dunlevs ?? 1;
}

/** C dungeon.c ledger_no — local. */
function ledger_no_maz(lev) {
    const dun = game.dungeons?.[lev?.dnum | 0];
    return ((dun?.ledger_start | 0) + (lev?.dlevel | 0)) | 0;
}

/** C hacklib.c upstart — capitalize first letter. */
function upstart_maz(str) {
    if (!str) return str;
    return str.charAt(0).toUpperCase() + str.slice(1);
}

/**
 * C ref: options.c fruitadd else (not user_specified) — orctown loot.
 * User-specified doset path stays in options.js (mklev↔options cycle).
 * Walker is live objnam fruit_from_name(FALSE) like C `:8264`.
 */
function fruitadd_orc(str) {
    let altname = '';
    const raw = String(str || '');
    const n = raw.length > 31 ? raw.slice(0, 31) : raw;
    for (let i = 0; i < n.length; i++) {
        const c = n.charCodeAt(i) & 0x7f;
        altname += (c < 0x20 || c === 0x7f) ? '.' : String.fromCharCode(c);
    }
    if (!game.flags) game.flags = {};
    game.flags.made_fruit = true;
    const look = altname || str;
    const highest = { fid: 0 };
    const found = fruit_from_name(look, false, highest);
    if (found) return found.fid | 0;
    if (highest.fid >= 127) return rnd(127);
    const f = {
        fname: String(look).slice(0, 31),
        fid: (highest.fid | 0) + 1,
        nextf: game.ffruit || null,
    };
    game.ffruit = f;
    return f.fid;
}

/** C objnam.c shiny_obj — rnd_otyp_by_namedesc("shiny", oclass, 0). */
function shiny_obj(oclass) {
    return rnd_otyp_by_namedesc('shiny', oclass, 0);
}

/**
 * C ref: mkmaze.c migrate_orc — send orc to a deeper mines level.
 * Leader: bottom (rarely −1) + MIGR_LEFTOVERS. Else random deeper.
 */
function migrate_orc(mtmp, mflags) {
    const uz = game.u?.uz || { dnum: 0, dlevel: 1 };
    const cur_depth = depth_of_level(uz) | 0;
    const max_depth = dunlevs_in_dungeon_maz(uz)
        + ((game.dungeons?.[uz.dnum | 0]?.depth_start | 0) - 1);
    let nlev;
    if (mflags === ORC_LEADER) {
        nlev = max_depth;
        if (!rn2(40)) nlev--;
        mtmp.migflags = (mtmp.migflags | 0) | MIGR_LEFTOVERS;
    } else {
        nlev = rn2((max_depth - cur_depth) + 1) + cur_depth;
        if (nlev === cur_depth) nlev++;
        if (nlev > max_depth) nlev = max_depth;
        mtmp.migflags = (mtmp.migflags | 0) & ~MIGR_LEFTOVERS;
    }
    const dest = { dnum: 0, dlevel: 0 };
    get_level(dest, nlev);
    migrate_to_level(mtmp, ledger_no_maz(dest), MIGR_RANDOM, null);
}

/**
 * C ref: mkmaze.c shiny_orc_stuff — gold/gem/shiny ring into minvent.
 */
function shiny_orc_stuff(mtmp) {
    const is_captain = (mtmp.data?.mndx | 0) === PM_ORC_CAPTAIN;
    const goldprob = is_captain ? 600 : 300;
    const gemprob = (goldprob / 4) | 0;
    if (rn2(1000) < goldprob) {
        const otmp = mksobj(GOLD_PIECE, true, false);
        if (otmp) {
            otmp.quan = 1 + rnd(goldprob);
            otmp.owt = weight(otmp);
            add_to_minv(mtmp, otmp);
        }
    }
    if (rn2(1000) < gemprob) {
        const otmp = mkobj(GEM_CLASS, false);
        if (otmp) {
            if (otmp.otyp === ROCK) dealloc_obj(otmp);
            else add_to_minv(mtmp, otmp);
        }
    }
    if (is_captain || !rn2(8)) {
        const otyp = shiny_obj(RING_CLASS);
        if (otyp !== STRANGE_OBJECT) {
            const otmp = mksobj(otyp, true, false);
            if (otmp) add_to_minv(mtmp, otmp);
        }
    }
}

/**
 * C ref: mkmaze.c migr_booty_item — mksobj_migr_to_species(M2_ORC) + gang
 * oname. Food: slime-mold fruitadd + quan += rn2(3).
 */
function migr_booty_item(otyp, gang) {
    const otmp = mksobj_migr_to_species(otyp, M2_ORC >>> 0, true, false);
    if (otmp && gang) {
        new_oname(otmp, gang.length + 1);
        if (!otmp.oextra) otmp.oextra = {};
        otmp.oextra.oname = gang;
        const oc = objects()?.[otyp];
        if ((oc?.oc_class | 0) === FOOD_CLASS) {
            if (otyp === SLIME_MOLD)
                otmp.spe = fruitadd_orc(orcfruit[rn2(orcfruit.length)]);
            otmp.quan += rn2(3);
            otmp.owt = weight(otmp);
        }
    }
}

/**
 * C ref: mkmaze.c stolen_booty — orctown loot onto migrating_objs and
 * fleeing orcs. Caller: fixup_special when mines && ransacked.
 * Arrival leftovers DF_ALL is D-1505. add_to_minv merge is D-1492.
 */
export function stolen_booty() {
    const gang = rndorcname();
    const gangCap = upstart_maz(gang);
    let cnt = rnd(4);
    for (let i = 0; i < cnt; ++i)
        migr_booty_item(rn2(4) ? TALLOW_CANDLE : WAX_CANDLE, gang);
    cnt = rnd(3);
    for (let i = 0; i < cnt; ++i)
        migr_booty_item(SKELETON_KEY, gang);
    const glove = rn1(
        (GAUNTLETS_OF_DEXTERITY - LEATHER_GLOVES) + 1, LEATHER_GLOVES,
    );
    migr_booty_item(glove, gang);
    cnt = rnd(10);
    for (let i = 0; i < cnt; ++i) {
        const otyp = rn1(TIN - TRIPE_RATION + 1, TRIPE_RATION);
        if (otyp !== LEMBAS_WAFER
            && ((objects()?.[otyp]?.oc_prob | 0) !== 0
                || otyp === C_RATION || otyp === K_RATION)
            && otyp !== CORPSE && otyp !== EGG && otyp !== TIN)
            migr_booty_item(otyp, gang);
    }
    migr_booty_item(rn2(2) ? LONG_SWORD : SILVER_SABER, gang);
    let mtmp = makemon(mons(PM_ORC_CAPTAIN), 0, 0, MM_NONAME);
    if (mtmp) {
        mtmp = christen_monst(mtmp, gangCap);
        mtmp.mpeaceful = 0;
        set_malign(mtmp);
        shiny_orc_stuff(mtmp);
        migrate_orc(mtmp, ORC_LEADER);
    }
    for (const mon of game.fmon || []) {
        if ((mon.mhp | 0) < 1) continue;
        if (is_orc(mon.data) && !has_mgivenname(mon) && rn2(10)) {
            if ((mon.data?.mndx | 0) !== PM_ORC_CAPTAIN)
                christen_orc(mon, gangCap, '');
        }
    }
    cnt = rn2(10) + 5;
    for (let i = 0; i < cnt; ++i) {
        const mtyp = rn2((PM_ORC_SHAMAN - PM_ORC) + 1) + PM_ORC;
        mtmp = makemon(mons(mtyp), 0, 0, MM_NONAME);
        if (mtmp) {
            shiny_orc_stuff(mtmp);
            migrate_orc(mtmp, 0);
        }
    }
    game.ransacked = 0;
}

// C ref: mkmaze.c fixup_special — post-special-level branch/lregion placement
function fixup_special() {
    // C: leftover gl.lregions. Other load_* still consume inline after
    // flip then call this (array empty). tut-1 leaves TELE for dest copy.
    // Fallback still uses made_branch: inline BRANCH would double-place
    // if this used C's added_branch-only gate.
    let added_branch = false;
    const lregions = game.lregions || [];
    game.lregions = [];
    for (const r of lregions) {
        switch (r.rtype) {
        case LR_BRANCH:
            added_branch = true;
            // fall through
        case LR_PORTAL:
        case LR_UPSTAIR:
        case LR_DOWNSTAIR: {
            let lev = null;
            if (r.rtype === LR_PORTAL) {
                const name = (r.rname && typeof r.rname === 'object')
                    ? r.rname.str : r.rname;
                if (name) {
                    if (name[0] >= '0' && name[0] <= '9') {
                        lev = {
                            dnum: game.u?.uz?.dnum | 0,
                            dlevel: parseInt(name, 10) | 0,
                        };
                    } else {
                        const sp = find_level(name);
                        if (sp?.dlevel) {
                            lev = {
                                dnum: sp.dlevel.dnum | 0,
                                dlevel: sp.dlevel.dlevel | 0,
                            };
                        }
                    }
                }
            }
            place_lregion(
                r.inarea.x1, r.inarea.y1, r.inarea.x2, r.inarea.y2,
                r.delarea.x1, r.delarea.y1, r.delarea.x2, r.delarea.y2,
                r.rtype, lev,
            );
            break;
        }
        case LR_TELE:
        case LR_UPTELE:
        case LR_DOWNTELE: {
            // C: copy dests only — place_lregion runs from goto_level
            // u_on_rndspot, not here.
            const tele = {
                lx: r.inarea.x1, ly: r.inarea.y1,
                hx: r.inarea.x2, hy: r.inarea.y2,
                nlx: r.delarea.x1, nly: r.delarea.y1,
                nhx: r.delarea.x2, nhy: r.delarea.y2,
            };
            if (r.rtype === LR_TELE || r.rtype === LR_UPTELE)
                game.updest = { ...tele };
            if (r.rtype === LR_TELE || r.rtype === LR_DOWNTELE)
                game.dndest = { ...tele };
            break;
        }
        }
    }
    if (!added_branch && !game.made_branch && is_branchlev()) {
        place_lregion(0, 0, 0, 0, 0, 0, 0, 0, LR_BRANCH, null);
    }

    // C ref: mkmaze.c fixup_special Is_medusa_level — statues in rooms[0]
    if (Is_medusa_level(game.u?.uz)) {
        const croom = game.level?.rooms?.[0];
        if (croom) {
            for (let tryct = rnd(4); tryct; tryct--) {
                const x = somex(croom);
                const y = somey(croom);
                if (goodpos(x, y, null, 0)) {
                    let tryct2 = 0;
                    const otmp = mk_tt_object(STATUE, x, y);
                    // Named omission: poly_when_stoned / pm_resistance MR_STONE
                    // retry loop (mresists not extracted) — keep first corpsenm.
                    void tryct2;
                    void otmp;
                }
            }
            let otmp;
            if (rn2(2))
                otmp = mk_tt_object(STATUE, somex(croom), somey(croom));
            else
                otmp = mkcorpstat(STATUE, null, null, somex(croom), somey(croom),
                    CORPSTAT_NONE);
            // Named omission: stone-resist corpsenm retry (same as above)
            void otmp;
        }
    }

    // C ref: mkmaze.c fixup_special on_level(baalzebub_level) → baalz_fixup
    if (Is_baal_level(game.u?.uz))
        baalz_fixup();

    // C mkmaze.c:694–695 — mines + ransacked → stolen_booty (orctown)
    if ((game.u?.uz?.dnum | 0) === (game.mines_dnum | 0) && game.ransacked)
        stolen_booty();

    // C ref: mkmaze.c fixup_special — Is_special && sp->flags.town → has_town
    {
        const uz = game.u?.uz;
        const sp = (game.sp_levchn || []).find(s0 =>
            (s0.dlevel?.dnum | 0) === (uz?.dnum | 0)
            && (s0.dlevel?.dlevel | 0) === (uz?.dlevel | 0));
        if (sp && sp.flags?.town) {
            if (!game.level.flags) game.level.flags = {};
            game.level.flags.has_town = true;
        }
    }
}

/**
 * C ref: stairs.c u_on_sstairs — place on special/branch staircase,
 * else u_on_rndspot(upflag) (D-1287; C :111–120). cmd.c
 * makemap_prepost post rndspot is D-1288.
 */
export async function u_on_sstairs(upflag) {
    const stway = stairway_find_special_dir(upflag);
    if (stway) {
        u_on_newpos(stway.sx, stway.sy);
        return;
    }
    await u_on_rndspot(upflag);
}

/**
 * C ref: stairs.c u_on_upstairs — ordinary upstairs, else
 * u_on_sstairs(0) ("destination upstairs implies moving down").
 */
export async function u_on_upstairs() {
    const stway = stairway_find_dir(true);
    if (stway) {
        u_on_newpos(stway.sx, stway.sy);
        return;
    }
    await u_on_sstairs(0);
}

/**
 * C ref: stairs.c u_on_dnstairs — ordinary downstairs, else
 * u_on_sstairs(1) ("destination dnstairs implies moving up").
 */
export async function u_on_dnstairs() {
    const stway = stairway_find_dir(false);
    if (stway) {
        u_on_newpos(stway.sx, stway.sy);
        return;
    }
    await u_on_sstairs(1);
}

// oinit — C ref: o_init.c oinit() → setgemprobs(&u.uz)
