function load_wiz_strt() {
    const g = game;
    nhlib_shuffle_align();
    splev_initlev({
        init_style: LVLINIT_SOLIDFILL,
        filling: STONE,
        lit: BOOL_RANDOM,
        icedpools: false,
    });
    if (!g.level.flags) g.level.flags = {};
    g.level.flags.is_maze_lev = true;
    g.level.flags.noteleport = true;
    g.level.flags.hardfloor = true;

    const WIZ_STRT_MAP = `
............................................................................
.....................C....CC.C........................C.....................
..........CCC.....................CCC.......................................
........CC........-----------.......C.C...C...C....C........................
.......C.....---------------------...C..C..C..C.............................
......C..C...------....\\....------....C.....C...............................
........C...||....|.........|....||.........................................
.......C....||....|.........+....||.........................................
.......C...||---+--.........|....|||........................................
......C....||...............|--S--||........................................
...........||--+--|++----|---|..|.SS..........C......C......................
........C..||.....|..|...|...|--|.||..CC..C.....C..........C................
.......C...||.....|..|.--|.|.|....||.................C..C...................
.....C......||....|..|.....|.|.--||..C..C..........C...........}}}..........
......C.C...||....|..-----.|.....||...C.C.C..............C....}}}}}}........
.........C...------........|------....C..C.....C..CC.C......}}}}}}}}}}}.....
.........CC..---------------------...C.C..C.....CCCCC.C.......}}}}}}}}......
.........C........-----------..........C.C.......CCC.........}}}}}}}}}......
..........C.C.........................C............C...........}}}}}........
......................CCC.C.................................................
`.replace(/^\n/, '');
    splev_apply_centered_map(WIZ_STRT_MAP);
    const mx = g.splev_xstart ?? 1;
    const my = g.splev_ystart ?? 0;

    // first do cloud everywhere; then clear tower interior
    lspo_replace_terrain_region(0, 0, 75, 19, ROOM, CLOUD, 10);
    lspo_replace_terrain_region(13, 5, 33, 15, CLOUD, ROOM, 100);

    // lit / unlit regions
    for (let y = my; y <= my + 19 && y < ROWNO; y++) {
        for (let x = mx; x <= mx + 75 && x < COLNO; x++) {
            const loc = g.level.at(x, y);
            if (loc) loc.lit = true;
        }
    }
    const unlitRect = (x1, y1, x2, y2) => {
        for (let y = my + y1; y <= my + y2 && y < ROWNO; y++) {
            for (let x = mx + x1; x <= mx + x2 && x < COLNO; x++) {
                const loc = g.level.at(x, y);
                if (loc) loc.lit = false;
            }
        }
    };
    unlitRect(35, 0, 49, 3);
    unlitRect(43, 12, 49, 16);
    unlitRect(30, 10, 31, 10);

    // des.region({ region={19,11,33,15}, lit=0, type="ordinary", irregular=1 })
    {
        const dx1 = mx + 19, dy1 = my + 11, dx2 = mx + 33, dy2 = my + 15;
        if ((g.level.nroom | 0) < MAXNROFROOMS) {
            add_room(dx1, dy1, dx2, dy2, false, OROOM, true);
            const troom = g.level.rooms[g.level.nroom - 1];
            if (troom) {
                troom.rlit = 0;
                troom.irregular = true;
                troom.needjoining = true;
                topologize(troom);
            }
        }
        unlitRect(19, 11, 33, 15);
    }

    // des.stair("down", 30,10)
    mkstairs(mx + 30, my + 10, 0, null);

    // Portal arrival point + branch levregion (pre-flip; flip remaps inarea)
    sel_set_ter(mx + 63, my + 6, ROOM, SET_LIT_NOCHANGE);
    g.lregions = g.lregions || [];
    g.lregions.push({
        rtype: LR_BRANCH,
        rname: null,
        inarea: {
            x1: mx + 63, y1: my + 6,
            x2: mx + 63, y2: my + 6,
        },
        delarea: { x1: -1, y1: -1, x2: -1, y2: -1 },
    });

    // Doors
    const wizDoor = (rx, ry, mask) => {
        const loc = g.level.at(mx + rx, my + ry);
        if (!loc) return;
        if (!IS_DOOR(loc.typ) && loc.typ !== SDOOR) loc.typ = DOOR;
        loc.doormask = mask;
        loc.flags = mask;
    };
    wizDoor(31, 9, D_CLOSED);
    wizDoor(16, 8, D_CLOSED);
    wizDoor(28, 7, D_CLOSED);
    wizDoor(34, 10, D_LOCKED);
    wizDoor(35, 10, D_LOCKED);
    wizDoor(15, 10, D_CLOSED);
    wizDoor(19, 10, D_LOCKED);
    wizDoor(20, 10, D_LOCKED);

    // Neferet the Green + custom invent
    {
        find_montype_gender('Neferet the Green');
        induced_align(80);
        const pmIdx = name_to_mon('Neferet the Green');
        const mtmp = pmIdx >= 0
            ? makemon(mons(pmIdx), mx + 23, my + 5, 0)
            : null;
        if (mtmp) {
            splev_discard_default_minvent(mtmp);
            for (const [otyp, spe] of [[ELVEN_CLOAK, 5], [QUARTERSTAFF, 5]]) {
                if (otyp < 0) continue;
                const pos = get_location_random(null);
                const otmp = mksobj_at(otyp, pos.x, pos.y, true, true);
                if (!otmp) continue;
                otmp.spe = spe;
                otmp.oeroded = 0;
                otmp.oeroded2 = 0;
                otmp.oerodeproof = 0;
                obj_extract_self(otmp);
                mpickobj(mtmp, otmp);
            }
        }
    }

    // treasure chest
    mksobj_at(CHEST, mx + 24, my + 5, true, true);

    const placeNamedAt = (id, rx, ry, peaceful) => {
        const { mndx, female } = find_montype_gender(id);
        const pm = (mndx >= 0 && mndx !== NON_PM) ? mons(mndx) : null;
        induced_align(80);
        const moved = splev_resolve_occupied(mx + rx, my + ry, pm);
        const mtmp = makemon(pm, moved.x, moved.y, 0);
        if (mtmp) {
            mtmp.female = female;
            if (peaceful != null && peaceful > BOOL_RANDOM)
                mtmp.mpeaceful = peaceful;
        }
    };
    const placeClassAt = (cls, rx, ry, peaceful) => {
        induced_align(80);
        const mlet = monclass_letter_to_mlet(cls);
        let pm = mlet ? mkclass(mlet, G_NOGEN) : null;
        pm = splev_mines_maybe_clear_your_race(pm);
        const moved = splev_resolve_occupied(mx + rx, my + ry, pm);
        const mtmp = pm ? makemon(pm, moved.x, moved.y, 0) : null;
        if (mtmp && peaceful != null && peaceful > BOOL_RANDOM)
            mtmp.mpeaceful = peaceful;
    };

    for (const [rx, ry] of [
        [30, 7], [24, 6], [15, 6], [15, 12], [26, 11], [27, 11], [19, 9], [20, 9],
    ]) placeNamedAt('apprentice', rx, ry);

    placeNamedAt('giant eel', 62, 14);
    placeNamedAt('giant eel', 69, 15);
    placeNamedAt('giant eel', 67, 17);

    // Non diggable walls
    for (let y = my; y <= my + 19 && y < ROWNO; y++) {
        for (let x = mx; x <= mx + 75 && x < COLNO; x++) {
            const loc = g.level.at(x, y);
            if (!loc) continue;
            if (IS_STWALL(loc.typ) || IS_TREE(loc.typ) || loc.typ === IRONBARS)
                loc.wall_info = (loc.wall_info || 0) | W_NONDIGGABLE;
        }
    }

    for (let i = 0; i < 6; i++) splev_create_trap();

    // Monsters on siege duty
    placeClassAt('B', 60, 9, 0);
    placeClassAt('W', 60, 10, 0);
    placeClassAt('B', 60, 11, 0);
    placeClassAt('B', 60, 12, 0);
    placeClassAt('i', 60, 13, 0);
    placeClassAt('B', 61, 10, 0);
    placeClassAt('B', 61, 11, 0);
    placeClassAt('B', 61, 12, 0);
    placeClassAt('B', 35, 3, 0);
    placeClassAt('i', 35, 17, 0);
    placeClassAt('B', 36, 17, 0);
    placeClassAt('B', 34, 16, 0);
    placeClassAt('i', 34, 17, 0);
    placeClassAt('W', 67, 2, 0);
    placeClassAt('B', 10, 19, 0);

    // C load_special epilogue: link_doors_rooms → remove_boundary_syms →
    // map_cleanup → wallification → flip_level_rnd → lregions → fixup
    link_doors_rooms();
    remove_boundary_syms();
    map_cleanup();
    if (!g.level.flags.corrmaze)
        wallification(1, 0, COLNO - 1, ROWNO - 1);
    flip_level_rnd(3, false);
    {
        const lregions = g.lregions || [];
        g.lregions = [];
        for (const r of lregions) {
            if (r.rtype === LR_BRANCH) {
                place_lregion(
                    r.inarea.x1, r.inarea.y1, r.inarea.x2, r.inarea.y2,
                    r.delarea.x1, r.delarea.y1, r.delarea.x2, r.delarea.y2,
                    LR_BRANCH, null,
                );
            }
        }
    }
    fixup_special();
}

/**
 * C ref: dat/Wiz-loca.lua via load_special — Wizard quest locate
 * (Guarded Tower / moat). solidfill + cloud/moat replace_terrain +
 * irregular rooms with secret doors + locked doors + traps/monsters.
 * Named omissions: humidity-aware get_location; spo_end_moninvent
 * m_dowear.
 */
function load_wiz_loca() {
    const g = game;
    nhlib_shuffle_align();
    splev_initlev({
        init_style: LVLINIT_SOLIDFILL,
        filling: STONE,
        lit: BOOL_RANDOM,
        icedpools: false,
    });
    if (!g.level.flags) g.level.flags = {};
    g.level.flags.is_maze_lev = true;
    g.level.flags.hardfloor = true;

    const WIZ_LOCA_MAP = `
.............        .......................................................
..............       .............}}}}}}}}}}}}}}}}}}}}}}}}}}}}}}}}}}}.......
..............      ..............}.................................}.......
..............      ..............}.-------------------------------.}.......
...............     .........C....}.|.............................|.}.......
...............    ..........C....}.|.---------------------------.|.}.......
...............    .........CCC...}.|.|.........................|.|.}.......
................   ....C....CCC...}.|.|.-----------------------.|.|.}.......
.......C..C.....  .....C....CCC...}.|.|.|......+.......+......|.|.|.}.......
.............C..CC.....C....CCC...}.|.|.|......|-------|......|.|.|.}.......
................   ....C....CCC...}.|.|.|......|.......|......|.|.|.}.......
......C..C.....    ....C....CCC...}.|.|.|......|-------|......|.|.|.}.......
............C..     ...C....CCC...}.|.|.|......+.......+......|.|.|.}.......
........C......    ....C....CCC...}.|.|.-----------------------.|.|.}.......
....C......C...     ........CCC...}.|.|.........................|.|.}.......
......C..C....      .........C....}.|.---------------------------.|.}.......
..............      .........C....}.|.............................|.}.......
.............       ..............}.-------------------------------.}.......
.............        .............}.................................}.......
.............        .............}}}}}}}}}}}}}}}}}}}}}}}}}}}}}}}}}}}.......
.............        .......................................................
`.replace(/^\n/, '');
    splev_apply_centered_map(WIZ_LOCA_MAP);
    const mx = g.splev_xstart ?? 1;
    const my = g.splev_ystart ?? 0;

    // des.replace_terrain — map-relative regions (ROOM/MOAT/CLOUD)
    lspo_replace_terrain_region(0, 0, 30, 20, ROOM, CLOUD, 15);
    lspo_replace_terrain_region(68, 0, 75, 20, ROOM, MOAT, 25);
    lspo_replace_terrain_region(34, 1, 68, 19, MOAT, ROOM, 2);

    // des.region(selection.area(00,00,75,20), "lit")
    for (let y = my; y <= my + 20 && y < ROWNO; y++) {
        for (let x = mx; x <= mx + 75 && x < COLNO; x++) {
            const loc = g.level.at(x, y);
            if (loc) loc.lit = true;
        }
    }

    const wizLocaAddIrregular = (x1, y1, lit, wallsOrRandom) => {
        const dx1 = mx + x1, dy1 = my + y1;
        if ((g.level.nroom | 0) >= MAXNROFROOMS) return null;
        const bounds = {
            min_rx: dx1, max_rx: dx1, min_ry: dy1, max_ry: dy1,
        };
        const rmno = g.level.nroom + ROOMOFFSET;
        if (g.smeq) g.smeq[g.level.nroom] = g.level.nroom;
        flood_fill_rm(dx1, dy1, rmno, lit, true, bounds);
        add_room(bounds.min_rx, bounds.min_ry, bounds.max_rx, bounds.max_ry,
            false, OROOM, true);
        const troom = g.level.rooms[g.level.nroom - 1];
        if (!troom) return null;
        troom.rlit = lit ? 1 : 0;
        troom.irregular = true;
        troom.needjoining = true;
        troom.needfill = 0;
        add_doors_to_room(troom);
        // contents: des.door({ state="secret", wall=... })
        if (wallsOrRandom === 'random') {
            splev_room_door(troom, 'secret', 'random');
        } else if (Array.isArray(wallsOrRandom)) {
            const wall = wallsOrRandom[lua_random2(1, wallsOrRandom.length) - 1];
            splev_room_door(troom, 'secret', wall);
        }
        return troom;
    };

    // irregular ordinary regions (lua order) + secret doors
    wizLocaAddIrregular(37, 4, false, 'random');
    wizLocaAddIrregular(39, 6, false, 'random');
    wizLocaAddIrregular(41, 8, true, ['north', 'south', 'west']);
    wizLocaAddIrregular(56, 8, true, ['north', 'south', 'east']);

    // des.region unlit corridor strips (lighting only)
    const unlitRect = (x1, y1, x2, y2) => {
        for (let y = my + y1; y <= my + y2 && y < ROWNO; y++) {
            for (let x = mx + x1; x <= mx + x2 && x < COLNO; x++) {
                const loc = g.level.at(x, y);
                if (loc) loc.lit = false;
            }
        }
    };
    unlitRect(48, 8, 54, 8);
    unlitRect(48, 12, 54, 12);

    wizLocaAddIrregular(48, 10, false, 'random');

    // des.door("locked", …)
    const wizDoor = (rx, ry, mask) => {
        const loc = g.level.at(mx + rx, my + ry);
        if (!loc) return;
        if (!IS_DOOR(loc.typ) && loc.typ !== SDOOR) loc.typ = DOOR;
        loc.doormask = mask;
        loc.flags = mask;
    };
    wizDoor(55, 8, D_LOCKED);
    wizDoor(55, 12, D_LOCKED);
    wizDoor(47, 8, D_LOCKED);
    wizDoor(47, 12, D_LOCKED);

    // des.terrain({03,17}, ".") then stairs
    sel_set_ter(mx + 3, my + 17, ROOM, SET_LIT_NOCHANGE);
    mkstairs(mx + 3, my + 17, 1, null);
    mkstairs(mx + 48, my + 10, 0, null);

    // des.non_diggable(selection.area(00,00,75,20))
    for (let y = my; y <= my + 20 && y < ROWNO; y++) {
        for (let x = mx; x <= mx + 75 && x < COLNO; x++) {
            const loc = g.level.at(x, y);
            if (!loc) continue;
            if (IS_STWALL(loc.typ) || IS_TREE(loc.typ) || loc.typ === IRONBARS)
                loc.wall_info = (loc.wall_info || 0) | W_NONDIGGABLE;
        }
    }

    // des.object() × 15
    for (let i = 0; i < 15; i++) splev_create_object(null);

    // Fixed traps then random-location traps
    const placeTrap = (ttyp, rx, ry) => {
        const ttmp = maketrap(mx + rx, my + ry, ttyp);
        mktrap_seen_victim(ttmp, {});
    };
    const placeTrapRnd = (ttyp) => {
        const pos = get_location_random(null);
        const ttmp = maketrap(pos.x, pos.y, ttyp);
        mktrap_seen_victim(ttmp, {});
    };
    for (const [rx, ry] of [
        [24, 2], [7, 10], [23, 5], [26, 19], [72, 2], [72, 12],
    ]) placeTrap(SPIKED_PIT, rx, ry);
    for (const [rx, ry] of [
        [45, 16], [65, 13], [55, 6], [39, 11], [57, 9],
    ]) placeTrap(ROCKTRAP, rx, ry);
    placeTrapRnd(MAGIC_TRAP);
    placeTrapRnd(STATUE_TRAP);
    placeTrapRnd(STATUE_TRAP);
    placeTrapRnd(POLY_TRAP);
    placeTrap(ANTI_MAGIC, 53, 10);
    placeTrapRnd(SLP_GAS_TRAP);
    placeTrapRnd(SLP_GAS_TRAP);
    placeTrapRnd(DART_TRAP);
    placeTrapRnd(DART_TRAP);
    placeTrapRnd(DART_TRAP);

    // des.monster — class B ×12, class i ×8, vampire bat ×7, class i ×1
    for (let i = 0; i < 12; i++) splev_create_monster('B', 0);
    for (let i = 0; i < 7; i++) splev_create_monster('i', 0);
    for (let i = 0; i < 7; i++) splev_create_monster('vampire bat');
    splev_create_monster('i', 0);

    // C load_special: link_doors_rooms → remove_boundary_syms →
    // map_cleanup → wallification → flip_level_rnd → fixup
    link_doors_rooms();
    remove_boundary_syms();
    map_cleanup();
    if (!g.level.flags.corrmaze)
        wallification(1, 0, COLNO - 1, ROWNO - 1);
    flip_level_rnd(3, false);
    fixup_special();
}

