                place_lregion(
                    r.inarea.x1, r.inarea.y1, r.inarea.x2, r.inarea.y2,
                    r.delarea.x1, r.delarea.y1, r.delarea.x2, r.delarea.y2,
                    LR_PORTAL, lev,
                );
