/**
 * C ref: dat/minetn-5.lua via load_special — Mines town "Grotto Town".
 * Solidfill + centered map + percent terrain + shops/temple/watch.
 * Named omissions: link_doors_rooms extras; ensure_way_out;
 * hellfill/asmodeus/baalz/orcus/juiblex/wizard1-3/fakewiz.
 * minetn-6 is D-1503. minetn-7 is D-1504.
 */
function load_minetn_5() {
    const g = game;
    nhlib_shuffle_align();
    const align = g.splev_align || ['law', 'neutral', 'chaos'];

    // des.level_init({ style = "solidfill", fg = " " })
    splev_initlev({
        init_style: LVLINIT_SOLIDFILL,
        filling: STONE,
        lit: BOOL_RANDOM,
        icedpools: false,
    });
    if (!g.level.flags) g.level.flags = {};
    g.level.flags.is_maze_lev = true;

    const MINETN5_MAP = `
-----         ---------                                                    
|...---  ------.......--    -------                       ---------------  
|.....----.........--..|    |.....|          -------      |.............|  
--..-....-.----------..|    |.....|          |.....|     --+---+--.----+-  
 --.--.....----     ----    |.....|  ------  --....----  |..-...--.-.+..|  
  ---.........----  -----   ---+---  |..+.|   ---..-..----..---+-..---..|  
    ----.-....|..----...--    |.|    |..|.|    ---+-.....-+--........--+-  
       -----..|....-.....---- |.|    |..|.------......--................|  
    ------ |..|.............---.--   ----.+..|-.......--..--------+--..--  
    |....| --......---...........-----  |.|..|-...{....---|.........|..--  
    |....|  |........-...-...........----.|..|--.......|  |.........|...|  
    ---+--------....-------...---......--.-------....---- -----------...|  
 ------.---...--...--..-..--...-..---...|.--..-...-....------- |.......--  
 |..|-.........-..---..-..---.....--....|........---...-|....| |.-------   
 |..+...............-+---+-----..--..........--....--...+....| |.|...S.    
-----.....{....----...............-...........--...-...-|....| |.|...|     
|..............-- --+--.---------.........--..-........------- |.--+-------
-+-----.........| |...|.|....|  --.......------...|....---------.....|....|
|...| --..------- |...|.+....|   ---...---    --..|...--......-...{..+..-+|
|...|  ----       ------|....|     -----       -----.....----........|..|.|
-----                   ------                     -------  ---------------
`.replace(/^\n/, '');
    const { xstart: mx, ystart: my } = splev_apply_centered_map(MINETN5_MAP);

    const setTer = (rx, ry, typ) => {
        sel_set_ter(mx + rx, my + ry, typ, SET_LIT_NOCHANGE);
    };
    const setLine = (x1, y1, x2, y2, typ) => {
        let x = x1, y = y1;
        const dx = Math.sign(x2 - x1);
        const dy = Math.sign(y2 - y1);
        for (;;) {
            setTer(x, y, typ);
            if (x === x2 && y === y2) break;
            x += dx;
            y += dy;
        }
    };
    const setArea = (x1, y1, x2, y2, typ) => {
        for (let y = y1; y <= y2; y++)
            for (let x = x1; x <= x2; x++)
                setTer(x, y, typ);
    };

    // percent terrain variants (C nhlib percent → rn2(100))
    if (percent(75)) {
        if (percent(50)) setLine(25, 8, 25, 9, VWALL);
        else setLine(16, 13, 17, 13, HWALL);
    }
    if (percent(75)) {
        if (percent(50)) setLine(36, 10, 36, 11, VWALL);
        else setLine(32, 15, 33, 15, HWALL);
    }
    if (percent(50)) {
        setArea(21, 4, 22, 5, ROOM);
        setLine(14, 9, 14, 10, VWALL);
    }
    if (percent(50)) {
        setTer(46, 13, VWALL);
        setLine(43, 5, 47, 5, HWALL);
        setLine(42, 6, 46, 6, ROOM);
        setLine(46, 7, 47, 7, ROOM);
    }
    if (percent(50)) {
        setArea(69, 11, 71, 11, HWALL);
    }

    // des.stair
    mkstairs(mx + 1, my + 1, 1, null);
    mkstairs(mx + 46, my + 3, 0, null);

    // des.feature fountain (map may already have '{')
    for (const [rx, ry] of [[50, 9], [10, 15], [66, 18]]) {
        const loc = g.level.at(mx + rx, my + ry);
        if (loc) loc.typ = FOUNTAIN;
    }

    // des.region(selection.area(...), "lit"|"unlit") — C lspo_region 2-arg:
    // lit grows selection W_ANY then sel_set_lit; unlit does not grow.
    // light_region expands the rect by 1 when lighting (same for solid areas)
    // so wallification's perimeter walls inherit .lit (D-0802).
    light_region(mx + 0, my + 0, mx + 74, my + 20, false);
    for (const [x1, y1, x2, y2] of [
        [9, 13, 11, 17], [8, 14, 12, 16],
        [49, 7, 51, 11], [48, 8, 52, 10],
        [64, 17, 68, 19],
        [37, 13, 39, 17], [36, 14, 40, 17],
        [59, 2, 72, 10],
    ]) light_region(mx + x1, my + y1, mx + x2, my + y2, true);

    // Town watch + gnomes/dwarves (random place)
    for (let i = 0; i < 4; i++) splev_create_monster('watchman', 1);
    splev_create_monster('watch captain', 1);
    for (let i = 0; i < 6; i++) splev_create_monster('gnome');
    splev_create_monster('gnome lord');
    splev_create_monster('gnome lord');
    for (let i = 0; i < 3; i++) splev_create_monster('dwarf');

    const addRectRoom = (x1, y1, x2, y2, lit, rtype) => {
        const dx1 = mx + x1, dy1 = my + y1, dx2 = mx + x2, dy2 = my + y2;
        if ((g.level.nroom | 0) >= MAXNROFROOMS) return null;
        add_room(dx1, dy1, dx2, dy2, lit, rtype, true);
        const troom = g.level.rooms[g.level.nroom - 1];
        if (!troom) return null;
        troom.rlit = lit ? 1 : 0;
        troom.needfill = FILL_NORMAL;
        troom.needjoining = true;
        topologize(troom);
        add_doors_to_room(troom);
        return troom;
    };
    const tnDoor = (rx, ry, mask) => {
        const loc = g.level.at(mx + rx, my + ry);
        if (!loc) return;
        if (!IS_DOOR(loc.typ) && loc.typ !== SDOOR) loc.typ = DOOR;
        loc.doormask = mask;
        loc.flags = mask;
    };
    const placeNamedAt = (id, rx, ry) => {
        const { mndx, female } = find_montype_gender(id);
        induced_align(80);
        let pm = (mndx >= 0 && mndx !== NON_PM) ? mons(mndx) : null;
        pm = splev_mines_maybe_clear_your_race(pm);
        let x = mx + rx, y = my + ry;
        const moved = splev_resolve_occupied(x, y, pm);
        x = moved.x; y = moved.y;
        const mtmp = makemon(pm, x, y, 0);
        if (mtmp && pm) mtmp.female = female;
    };
    const placeClassAt = (cls, rx, ry) => {
        induced_align(80);
        const mlet = monclass_letter_to_mlet(cls);
        let pm = mlet ? mkclass(mlet, G_NOGEN) : null;
        pm = splev_mines_maybe_clear_your_race(pm);
        let x = mx + rx, y = my + ry;
        const moved = splev_resolve_occupied(x, y, pm);
        x = moved.x; y = moved.y;
        if (pm) makemon(pm, x, y, 0);
    };

    // Shops
    addRectRoom(25, 17, 28, 19, true, CANDLESHOP);
    tnDoor(24, 18, D_CLOSED);
    addRectRoom(59, 9, 67, 10, true, SHOPBASE);
    tnDoor(66, 8, D_CLOSED);
    addRectRoom(57, 13, 60, 15, true, TOOLSHOP);
    tnDoor(56, 14, D_CLOSED);
    addRectRoom(5, 9, 8, 10, true, splev_roomtype(monkfoodshop()));
    tnDoor(7, 11, D_CLOSED);

    // Gnome homes
    tnDoor(4, 14, D_CLOSED);
    tnDoor(1, 17, D_LOCKED);
    placeNamedAt('gnomish wizard', 2, 19);
    tnDoor(20, 16, D_LOCKED);
    placeClassAt('G', 20, 18);
    tnDoor(21, 14, rnddoor());
    tnDoor(25, 14, rnddoor());
    tnDoor(42, 8, rnddoor());
    tnDoor(40, 5, D_LOCKED);
    placeClassAt('G', 38, 7);
    tnDoor(59, 3, rnddoor());
    tnDoor(58, 6, rnddoor());
    tnDoor(63, 3, rnddoor());
    tnDoor(63, 5, rnddoor());
    tnDoor(71, 3, D_LOCKED);
    tnDoor(71, 6, D_LOCKED);
    tnDoor(69, 4, D_CLOSED);
    tnDoor(67, 16, D_CLOSED);
    placeNamedAt('gnomish wizard', 67, 14);
    mkobj_at(RING_CLASS, mx + 70, my + 14, true);
    tnDoor(69, 18, D_LOCKED);
    placeNamedAt('gnome lord', 71, 19);
    tnDoor(73, 18, D_LOCKED);
    mksobj_at(CHEST, mx + 73, my + 19, true, true);
    tnDoor(50, 6, D_LOCKED);
    mkobj_at(TOOL_CLASS, mx + 50, my + 3, true);
    {
        const statue = mksobj_at(STATUE, mx + 38, my + 15, true, true);
        if (statue) {
            statue.spe = CORPSTAT_HISTORIC;
            const pmIdx = name_to_mon('gnome king');
            if (pmIdx >= 0 && pmIdx !== NON_PM) set_corpsenm(statue, pmIdx);
        }
    }

    // Temple
    const templeRoom = addRectRoom(29, 2, 33, 4, true, TEMPLE);
    tnDoor(31, 5, D_CLOSED);
    {
        const ax = mx + 31, ay = my + 3;
        const loc = g.level.at(ax, ay);
        const alignStrToAmask = (s) => {
            if (s === 'law') return AM_LAWFUL;
            if (s === 'neutral') return AM_NEUTRAL;
            if (s === 'chaos') return AM_CHAOTIC;
            return AM_NEUTRAL;
        };
        // Lua align[1] → JS align[0]
        const amask = alignStrToAmask(align[0]) | AM_SHRINE;
        if (loc) {
            loc.typ = ALTAR;
            loc.flags = amask;
            loc.altarmask = amask;
        }
        if (templeRoom) priestini(g.u?.uz, templeRoom, ax, ay, false);
        if (g.level.flags) g.level.flags.has_temple = true;
    }

    // C load_special: wallification → flip → fixup
    if (!g.level.flags.corrmaze)
        wallification(1, 0, COLNO - 1, ROWNO - 1);
    flip_level_rnd(3, false);
    fixup_special();
}

/**
 * C ref: dat/minetn-6.lua via load_special — Mines town "Bustling Town".
 * Solidfill then mines (lit=1, bg HWALL) + top-aligned map ('x' keeps
 * cavern) + shops/temple/watch. Named omissions:
 * link_doors_rooms extras; ensure_way_out (lua inaccessibles flag);
 * map_cleanup; count_level_features. minetn-7 is D-1504.
 */
async function load_minetn_6() {
    const g = game;
    nhlib_shuffle_align();
    const align = g.splev_align || ['law', 'neutral', 'chaos'];

    // des.level_init({ style = "solidfill", fg = " " })
    splev_initlev({
        init_style: LVLINIT_SOLIDFILL,
        filling: STONE,
        lit: BOOL_RANDOM,
        icedpools: false,
    });

    // des.level_flags("mazelevel", "inaccessibles") — ensure_way_out named
    if (!g.level.flags) g.level.flags = {};
    g.level.flags.is_maze_lev = true;

    // des.level_init({ style="mines", fg=".", bg="-", smoothed=true,
    // joined=true, lit=1, walled=true }) — filling defaults to fg
    await splev_initlev({
        init_style: LVLINIT_MINES,
        fg: ROOM, bg: HWALL, filling: ROOM,
        lit: 1, smoothed: true, joined: true, walled: true,
        icedpools: false,
    });

    const MINETN6_MAP = `
x--------xxxxxxxxxxx-------------------x
x------xxxxxxxxxxxxxx-----------------xx
.-----................----------------.x
.|...|................|...|..|...|...|..
.|...+..--+--.........|...|..|...|...|..
.|...|..|...|..-----..|...|..|-+---+--..
.-----..|...|--|...|..--+---+-.........x
........|...|..|...+.............-----.x
........-----..|...|......--+-...|...|..
x----...|...|+------..{...|..|...+...|..
x|..+...|...|.............|..|...|...|..
.|..|...|...|-+-.....---+-------------.x
.----...--+--..|..-+-|..................
...|........|..|..|..|----....--------.x
...|..T.....----..|..|...+....|......|..
...|-....{........|..|...|....+......|x.
...--..-....T.....--------....|......|x.
.......--.....................----------
.xxxx-----xxxxxxxxxxxxxxxxxx------------
xxxx-------xxxxxxxxxxxxxxx--------------
`.replace(/^\n/, '');
    const mf = mapfrag_fromstr(MINETN6_MAP);
    const { xstart: mx, ystart: my } = splev_map_aligned_start(
        mf.wid, mf.hei, 'center', 'top',
    );
    g.splev_xstart = mx;
    g.splev_ystart = my;
    g.splev_xsize = mf.wid;
    g.splev_ysize = mf.hei;
    if (!g.SpLev_Map) g.SpLev_Map = new Set();
    for (let yy = my; yy < Math.min(ROWNO, my + mf.hei); yy++) {
        for (let xx = mx; xx < Math.min(COLNO, mx + mf.wid); xx++) {
            const mptyp = mapfrag_get(mf, xx - mx, yy - my);
            // C lspo_map: 'x' → MAX_TYPE skip (keep mines cavern)
            if (mptyp === INVALID_TYPE || mptyp >= MAX_TYPE) continue;
            sel_set_ter(xx, yy, mptyp, false);
            g.SpLev_Map.add(`${xx},${yy}`);
        }
    }
    // C lspo_map table form lit=FALSE → set_levltyp_lit on written cells
    {
        const sp = g.SpLev_Map;
        if (sp) {
            for (const key of sp) {
                const comma = key.indexOf(',');
                const x = Number(key.slice(0, comma));
                const y = Number(key.slice(comma + 1));
                const loc = g.level.at(x, y);
                if (!loc) continue;
                loc.lit = IS_LAVA(loc.typ) ? true : false;
            }
        }
    }

    // des.region(selection.area(00,00,39,19), "lit") — grow + sel_set_lit
    light_region(mx + 0, my + 0, mx + 39, my + 19, true);

    // des.levregion stair-up / stair-down — region_islev=1; exclude map-rel
    const pushLev = (rtype, region, exclude) => {
        levregion_add({
            inarea: {
                x1: region[0] | 0, y1: region[1] | 0,
                x2: region[2] | 0, y2: region[3] | 0,
            },
            delarea: {
                x1: exclude[0] | 0, y1: exclude[1] | 0,
                x2: exclude[2] | 0, y2: exclude[3] | 0,
            },
            in_islev: true,
            del_islev: false,
            rtype,
            padding: 0,
            rname: { str: null },
        });
    };
    pushLev(LR_UPSTAIR, [1, 3, 21, 19], [1, 0, 39, 18]);
    pushLev(LR_DOWNSTAIR, [60, 3, 75, 19], [0, 0, 38, 18]);

    // des.region(selection.area(13,7,14,8), "unlit") — no grow
    light_region(mx + 13, my + 7, mx + 14, my + 8, false);

    const addRectRoom = (x1, y1, x2, y2, lit, rtype) => {
        const dx1 = mx + x1, dy1 = my + y1, dx2 = mx + x2, dy2 = my + y2;
        if ((g.level.nroom | 0) >= MAXNROFROOMS) return null;
        add_room(dx1, dy1, dx2, dy2, lit, rtype, true);
        const troom = g.level.rooms[g.level.nroom - 1];
        if (!troom) return null;
        troom.rlit = lit ? 1 : 0;
        troom.needfill = FILL_NORMAL;
        troom.needjoining = true;
        topologize(troom);
        add_doors_to_room(troom);
        return troom;
    };
    const tnDoor = (rx, ry, mask) => {
        const loc = g.level.at(mx + rx, my + ry);
        if (!loc) return;
        if (!IS_DOOR(loc.typ) && loc.typ !== SDOOR) loc.typ = DOOR;
        loc.doormask = mask;
        loc.flags = mask;
    };
    const placeNamedAt = (id, rx, ry) => {
        const { mndx, female } = find_montype_gender(id);
        induced_align(80);
        let pm = (mndx >= 0 && mndx !== NON_PM) ? mons(mndx) : null;
        pm = splev_mines_maybe_clear_your_race(pm);
        let x = mx + rx, y = my + ry;
        const moved = splev_resolve_occupied(x, y, pm);
        x = moved.x; y = moved.y;
        const mtmp = makemon(pm, x, y, 0);
        if (mtmp && pm) mtmp.female = female;
    };

    // des.region filled shops / temple (needfill later in makelevel)
    addRectRoom(9, 9, 11, 11, true, CANDLESHOP);
    addRectRoom(16, 6, 18, 8, true, TOOLSHOP);
    addRectRoom(23, 3, 25, 5, true, SHOPBASE);
    addRectRoom(22, 14, 24, 15, true, splev_roomtype(monkfoodshop()));
    const templeRoom = addRectRoom(31, 14, 36, 16, true, TEMPLE);

    // des.altar align[1] shrine — Lua 1-based → JS align[0]
    {
        const ax = mx + 35, ay = my + 15;
        const loc = g.level.at(ax, ay);
        const alignStrToAmask = (s) => {
            if (s === 'law') return AM_LAWFUL;
            if (s === 'neutral') return AM_NEUTRAL;
            if (s === 'chaos') return AM_CHAOTIC;
            return AM_NEUTRAL;
        };
        const amask = alignStrToAmask(align[0]) | AM_SHRINE;
        if (loc) {
            loc.typ = ALTAR;
            loc.flags = amask;
            loc.altarmask = amask;
        }
        if (templeRoom) priestini(g.u?.uz, templeRoom, ax, ay, false);
        if (g.level.flags) g.level.flags.has_temple = true;
    }

    tnDoor(5, 4, D_CLOSED);
    tnDoor(4, 10, D_LOCKED);
    tnDoor(10, 4, D_CLOSED);
    tnDoor(10, 12, D_CLOSED);
    tnDoor(13, 9, D_LOCKED);
    tnDoor(14, 11, D_LOCKED);
    tnDoor(19, 7, D_CLOSED);
    tnDoor(19, 12, D_CLOSED);
    tnDoor(24, 6, D_CLOSED);
    tnDoor(24, 11, D_CLOSED);
    tnDoor(25, 14, D_CLOSED);
    tnDoor(28, 6, D_CLOSED);
    tnDoor(28, 8, D_LOCKED);
    tnDoor(30, 15, D_CLOSED);
    tnDoor(31, 5, D_CLOSED);
    tnDoor(35, 5, D_CLOSED);
    tnDoor(33, 9, D_CLOSED);

    for (let i = 0; i < 6; i++) splev_create_monster('gnome');
    placeNamedAt('gnome', 14, 8);
    placeNamedAt('gnome lord', 14, 7);
    placeNamedAt('gnome', 27, 10);
    splev_create_monster('gnome lord');
    splev_create_monster('gnome lord');
    splev_create_monster('dwarf');
    splev_create_monster('dwarf');
    splev_create_monster('dwarf');
    splev_create_monster('dwarf', 1);
    splev_create_monster('dwarf', 1);
    splev_create_monster('gnome', 1);
    splev_create_monster('gnome', 1);
    splev_create_monster('hobbit', 1);
    splev_create_monster('goblin', 1);
    splev_create_monster('kobold', 1);
    splev_create_monster('dog', 1);
    splev_create_monster('watchman', 1);
    splev_create_monster('watchman', 1);
    splev_create_monster('watchman', 1);
    splev_create_monster('watch captain', 1);
    splev_create_monster('watch captain', 1);

    // C load_special: wallification → flip → fixup
    if (!g.level.flags.corrmaze)
        wallification(1, 0, COLNO - 1, ROWNO - 1);
    flip_level_rnd(3, false);
    fixup_special();
}

