/**
 * C ref: mkmaze.c setup_waterlevel — air/water bubble grid + stone→AIR/WATER.
 * Named omission: full bubble cons / movebubbles body beyond initial paint.
 */
function setup_waterlevel() {
    const g = game;
    const uz = g.u?.uz;
    if (!Is_waterlevel(uz) && !Is_airlevel(uz)) return;
    if (!g.level.flags) g.level.flags = {};
    g.level.flags.hero_memory = false;

    const xmin = 3;
    const ymin = 1;
    let xmax = 78;
    if (xmax > COLNO - 2) xmax = COLNO - 2;
    let ymax = 20;
    if (ymax > ROWNO - 1) ymax = ROWNO - 1;
    const gbxmin = xmin + 1;
    const gbymin = ymin + 1;
    const gbxmax = xmax - 1;
    const gbymax = ymax - 1;
    g.waterlevel_bounds = { xmin, ymin, xmax, ymax, gbxmin, gbymin, gbxmax, gbymax };

    // C: glyph = cmap_to_glyph(water ? S_water : S_air); set on every cell
    const memGlyph = Is_waterlevel(uz)
        ? { ch: '}', color: CLR_BRIGHT_BLUE, decgfx: false }
        : { ch: ' ', color: CLR_CYAN, decgfx: false };
    const typ = Is_waterlevel(uz) ? WATER : AIR;
    for (let x = 1; x <= COLNO - 1; x++) {
        for (let y = 0; y <= ROWNO - 1; y++) {
            const loc = g.level.at(x, y);
            if (!loc) continue;
            loc.remembered_glyph = { ...memGlyph };
            if (loc.typ === STONE) loc.typ = typ;
        }
    }

    let xskip, yskip;
    if (Is_waterlevel(uz)) {
        xskip = 10 + rn2(10);
        yskip = 4 + rn2(4);
    } else {
        xskip = 6 + rn2(4);
        yskip = 3 + rn2(3);
    }

    g.bbubbles = null;
    g.ebubbles = null;
    g.wportal = null;
    for (let x = gbxmin; x <= gbxmax; x += xskip) {
        for (let y = gbymin; y <= gbymax; y += yskip) {
            mk_bubble(x, y, rn2(7), gbxmin, gbymin, gbxmax, gbymax);
        }
    }
}

/** C ref: mkmaze.c mk_bubble + mv_bubble(ini) cloud/air paint RNG. */
function mk_bubble(x, y, n, gbxmin, gbymin, gbxmax, gbymax) {
    const BM = [
        [2, 1, 0x3],
        [3, 2, 0x7, 0x7],
        [4, 3, 0x6, 0xf, 0x6],
        [5, 3, 0xe, 0x1f, 0xe],
        [6, 4, 0x1e, 0x3f, 0x3f, 0x1e],
        [7, 4, 0x3e, 0x7f, 0x7f, 0x3e],
        [8, 4, 0x7e, 0xff, 0xff, 0x7e],
    ];
    if (x >= gbxmax || y >= gbymax) return;
    if (n >= BM.length) n = BM.length - 1;
    const bm = BM[n];
    let bx = x;
    let by = y;
    if ((bx + bm[0] - 1) > gbxmax) bx = gbxmax - bm[0] + 1;
    if ((by + bm[1] - 1) > gbymax) by = gbymax - bm[1] + 1;
    const dx = 1 - rn2(3);
    const dy = 1 - rn2(3);
    // C: mv_bubble(b, 0, 0, TRUE) — air clouds skip move unless !rn2(6)
    if (!Is_airlevel(game.u?.uz) || !rn2(6)) {
        // ini move with dx=dy=0 — no position change; still burns air rn2(6)
        void dx;
        void dy;
    }
    // paint bubble cells: water→AIR, air→CLOUD
    const paint = Is_waterlevel(game.u?.uz) ? AIR : CLOUD;
    for (let i = 0; i < bm[0]; i++) {
        for (let j = 0; j < bm[1]; j++) {
            if (bm[j + 2] & (1 << i)) {
                const loc = game.level.at(bx + i, by + j);
                if (loc) {
                    loc.typ = paint;
                    loc.lit = true;
                }
            }
        }
    }
    const b = {
        x: bx, y: by, dx, dy, bm: bm.slice(), cons: null, next: null, prev: null,
    };
    if (!game.bbubbles)
        game.bbubbles = b;
    if (game.ebubbles) {
        game.ebubbles.next = b;
        b.prev = game.ebubbles;
    } else {
        b.prev = null;
    }
    b.next = null;
    game.ebubbles = b;
}

/**
 * C ref: mkmaze.c movebubbles — air edge clouds + bubble drift (goto_level /
 * moveloop). Named omission: water cons pickup/deposit; Punished ball.
 */
export function movebubbles() {
    const g = game;
    const uz = g.u?.uz;
    if (!Is_waterlevel(uz) && !Is_airlevel(uz)) return;

    if (!g.wportal)
        set_wportal();

    const bounds = g.waterlevel_bounds || {
        gbxmin: 4, gbymin: 2, gbxmax: 77, gbymax: 19,
    };
    const { gbxmin, gbymin, gbxmax, gbymax } = bounds;

    if (Is_airlevel(uz)) {
        // C: levl[x][y] = air_pos — glyph S_cloud, typ AIR, lit 1
        // (docrt paints lev->glyph for the whole map before vision).
        const airGlyph = { ch: '#', color: CLR_GRAY, decgfx: false };
        for (let x = 1; x <= COLNO - 1; x++) {
            for (let y = 0; y <= ROWNO - 1; y++) {
                const loc = g.level.at(x, y);
                if (!loc) continue;
                loc.remembered_glyph = { ...airGlyph };
                loc.typ = AIR;
                loc.lit = true;
                const xedge = x < gbxmin || x > gbxmax;
                const yedge = y < gbymin || y > gbymax;
                if (xedge || yedge) {
                    if (!rn2(xedge ? 3 : 5)) {
                        loc.typ = CLOUD;
                    }
                }
            }
        }
    }
    // water bubble cons pickup deferred

    g.movebubbles_up = !g.movebubbles_up;
    const up = !!g.movebubbles_up;
    // C: traverse bbubbles forward or ebubbles reverse on alternate turns
    for (let b = up ? g.bbubbles : g.ebubbles; b; b = up ? b.next : b.prev) {
        const rx = rn2(3);
        const ry = rn2(3);
        const mdx = b.dx + 1 - (!b.dx ? rx : (rx ? 1 : 0));
        const mdy = b.dy + 1 - (!b.dy ? ry : (ry ? 1 : 0));
        mv_bubble_move(b, mdx, mdy, gbxmin, gbymin, gbxmax, gbymax, false);
    }
    g.vision_full_recalc = 1;
}

/** C ref: mkmaze.c mv_bubble — air rn2(6) skip + CLOUD/AIR paint + boing. */
function mv_bubble_move(b, dx, dy, gbxmin, gbymin, gbxmax, gbymax, ini) {
    let colli = 0;
    if (!Is_airlevel(game.u?.uz) || !rn2(6)) {
        let mdx = dx;
        let mdy = dy;
        if (mdx < -1 || mdx > 1 || mdy < -1 || mdy > 1) {
            mdx = Math.sign(mdx);
            mdy = Math.sign(mdy);
        }
        if (b.x <= gbxmin) colli |= 2;
        if (b.y <= gbymin) colli |= 1;
        if ((b.x + b.bm[0] - 1) >= gbxmax) colli |= 2;
        if ((b.y + b.bm[1] - 1) >= gbymax) colli |= 1;
        if (b.x === gbxmin && mdx < 0) mdx = -mdx;
        if (b.x + b.bm[0] - 1 === gbxmax && mdx > 0) mdx = -mdx;
        if (b.y === gbymin && mdy < 0) mdy = -mdy;
        if (b.y + b.bm[1] - 1 === gbymax && mdy > 0) mdy = -mdy;
        b.x += mdx;
        b.y += mdy;
    }
    const paint = Is_waterlevel(game.u?.uz) ? AIR : CLOUD;
    for (let i = 0; i < b.bm[0]; i++) {
        for (let j = 0; j < b.bm[1]; j++) {
            if (b.bm[j + 2] & (1 << i)) {
                const loc = game.level.at(b.x + i, b.y + j);
                if (loc) {
                    loc.typ = paint;
                    loc.lit = true;
                }
            }
        }
    }
    // C: boing — sometimes alter direction (!ini path; movebubbles uses FALSE)
    switch (colli) {
    case 1:
        b.dy = -b.dy;
        break;
    case 3:
        b.dy = -b.dy;
        // FALLTHROUGH
    case 2:
        b.dx = -b.dx;
        break;
    default:
        if (!ini && ((b.dx || b.dy) ? !rn2(20) : !rn2(5))) {
            b.dx = 1 - rn2(3);
            b.dy = 1 - rn2(3);
        }
        break;
    }
}

/**
 * C ref: mkmaze.c set_wportal — first MAGIC_PORTAL on the trap chain.
 * Named omit: impossible("set_wportal(): no portal!") pline.
 */
export function set_wportal() {
    const g = game;
    const traps = g.level?.traps;
    if (Array.isArray(traps)) {
        for (const t of traps) {
            if (t && (t.ttyp | 0) === MAGIC_PORTAL) {
                g.wportal = t;
                return;
            }
        }
    }
    for (let t = g.ftrap; t; t = t.ntrap) {
        if ((t.ttyp | 0) === MAGIC_PORTAL) {
            g.wportal = t;
            return;
        }
    }
}

/**
 * C ref: mkmaze.c save_waterlevel update_file arm — JSON analogue of
 * Sfo_int n/xmin/ymin/xmax/ymax + Sfo_bubble. Does not unsetup
 * (C release_data arm is unsetup_waterlevel, called from goto_level).
 * Named omit: cons pointers (always 0 at save).
 */
export function save_waterlevel() {
    const g = game;
    if (!g.bbubbles) return null;
    const bounds = g.waterlevel_bounds || { xmin: 3, ymin: 1, xmax: 78, ymax: 20 };
    const bubbles = [];
    for (let b = g.bbubbles; b; b = b.next) {
        bubbles.push({
            x: b.x | 0,
            y: b.y | 0,
            dx: b.dx | 0,
            dy: b.dy | 0,
            bm: Array.from(b.bm || []),
        });
    }
    return {
        xmin: bounds.xmin | 0,
        ymin: bounds.ymin | 0,
        xmax: bounds.xmax | 0,
        ymax: bounds.ymax | 0,
        bubbles,
    };
}

/**
 * C ref: mkmaze.c unsetup_waterlevel — free the bubble chain.
 * Also drop wportal so the next plane re-runs set_wportal.
 */
export function unsetup_waterlevel() {
    const g = game;
    g.bbubbles = null;
    g.ebubbles = null;
    g.wportal = null;
}

/**
 * C ref: mkmaze.c restore_waterlevel — rebuild bbubbles/ebubbles from
 * the save blob, then mv_bubble(b, 0, 0, TRUE) per bubble.
 * Named omit: something_worth_saving / impossible on n==0.
 */
export function restore_waterlevel(blob) {
    const g = game;
    if (!blob || !Array.isArray(blob.bubbles)) return;
    const xmin = blob.xmin | 0;
    const ymin = blob.ymin | 0;
    const xmax = blob.xmax | 0;
    const ymax = blob.ymax | 0;
    g.waterlevel_bounds = {
        xmin, ymin, xmax, ymax,
        gbxmin: xmin + 1, gbymin: ymin + 1,
        gbxmax: xmax - 1, gbymax: ymax - 1,
    };
    const { gbxmin, gbymin, gbxmax, gbymax } = g.waterlevel_bounds;
    g.bbubbles = null;
    g.ebubbles = null;
    let b = null;
    for (let i = 0; i < blob.bubbles.length; i++) {
        const raw = blob.bubbles[i];
        const btmp = b;
        b = {
            x: raw.x | 0,
            y: raw.y | 0,
            dx: raw.dx | 0,
            dy: raw.dy | 0,
            bm: Array.from(raw.bm || []),
            cons: null,
            prev: null,
            next: null,
        };
        if (btmp) {
            btmp.next = b;
            b.prev = btmp;
        } else {
            g.bbubbles = b;
            b.prev = null;
        }
        mv_bubble_move(b, 0, 0, gbxmin, gbymin, gbxmax, gbymax, true);
    }
    g.ebubbles = b;
    if (b) b.next = null;
}

/**
 * C ref: mkmaze.c fumaroles — gas-cloud bursts on lava (arrival / moveloop).
 * make_gas_cloud set_heros_fault when !in_mklev; C then clear_heros_fault
 * so natural steam is not the hero's (killed vs monkilled). Norep whoosh
 * after the loop if any burst and !Deaf (D-1156).
 * Moveloop EOT caller D-1168; goto_level already wired.
 */
export async function fumaroles() {
    const g = game;
    const lf = g.level?.flags;
    if (!lf?.fumaroles) return;
    let nmax = rn2(3);
    let sizemin = 5;
    let snd = false;
    let loud = false;
    if (Is_firelevel(g.u?.uz)) {
        nmax++;
        sizemin += 5;
    }
    if ((lf.temperature | 0) > 0) {
        nmax++;
        sizemin += 5;
    }
    for (let n = nmax; n; n--) {
        const x = rn1(COLNO - 4, 3);
        const y = rn1(ROWNO - 4, 3);
        if (g.level.at(x, y)?.typ === LAVAPOOL) {
            const r = await create_gas_cloud(x, y, rn1(10, sizemin), rn1(10, 5));
            clear_heros_fault(r);
            snd = true;
            if (dist2(x, y, g.u?.ux | 0, g.u?.uy | 0) < 15) loud = true;
        }
    }
    if (snd && !Deaf_fumaroles()) {
        await Norep(`You hear a ${loud ? 'loud ' : ''}whoosh!`);
    }
}

/** C youprop.h Deaf — HDeaf || EDeaf || uroleplay.deaf. */
function Deaf_fumaroles() {
    const u = game.u || {};
    return !!((u.HDeaf | 0) || (u.EDeaf | 0) || u.uroleplay?.deaf || u.Deaf);
}

